package com.prokxi.dimples.domain;

import java.util.Objects;
import java.util.UUID;

/**
 * Identifies a golfer. Generated by the application when the golfer is created
 * (decision-2).
 */
public record GolferId(UUID value) {

	public GolferId {
		Objects.requireNonNull(value, "value must not be null");
	}

	public static GolferId generate() {
		return new GolferId(UUID.randomUUID());
	}

}
